float remap(float val, float inMin, float inMax, float outMin, float outMax)
{
    return outMin + (val - inMin) * (outMax - outMin) / (inMax - inMin);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    float remappedX = remap(iMouse.x, 0., iResolution.x, 0., 1.);
    float remappedY = remap(iMouse.y, 0., iResolution.y, 0., 1.);

    // control smoothline 
    float bottomSmothvalue1 = remappedX;
    float bottomSmothvalue2 = remappedY;

    // control smoothstep of line
    float smooth1 = 0.;
    float smooth2 = 0.005;


    vec3 col = vec3(1.);
    vec3 white = vec3(1.);
    vec3 black = vec3(0.);
    vec3 blue = vec3(0.,0.,1.);
    vec3 red = vec3(1.,0.,0.);

    float smoothStepLine = smoothstep(smooth1, smooth2, abs(uv.y - mix(0., 1., 
    smoothstep(bottomSmothvalue1, bottomSmothvalue2, uv.x))));

    col = mix(red, blue, smoothstep(bottomSmothvalue1, bottomSmothvalue2, uv.x));
    col = mix(white, col, smoothStepLine);

    fragColor = vec4(col,1.0);
}
